const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    // Approximate coordinates for Lake Menindee, Australia
    const point = ee.Geometry.Point(141.83, -32.38);
    // Define a polygon around Lake Menindee to capture its extent.
    // This is a rough bounding box for the lake area.
    const geometry = ee.Geometry.Polygon(
      [[[141.65, -32.25],
        [142.15, -32.25],
        [142.15, -32.55],
        [141.65, -32.55],
        [141.65, -32.25]]], null, false);

    const date1_start = '2019-01-18'; // Approx. 15 days before Feb 2, 2019
    const date1_end = '2019-02-17';   // Approx. 15 days after Feb 2, 2019

    const date2_start = '2021-04-29'; // Approx. 15 days before May 14, 2021
    const date2_end = '2021-05-29';   // Approx. 15 days after May 14, 2021

    // 2. Data Acquisition & Check

    // Sentinel-2 cloud masking function
    function maskS2clouds(image) {
      const qa = image.select('QA60');
      // Bits 10 and 11 are clouds and cirrus, respectively.
      const cloudBitMask = 1 << 10;
      const cirrusBitMask = 1 << 11;
      // Both flags should be set to zero, indicating clear conditions.
      const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
                   .and(qa.bitwiseAnd(cirrusBitMask).eq(0));
      // Return the masked and scaled image, selecting only reflectance bands.
      return image.updateMask(mask).divide(10000).select(['B.*']);
    }

    // Function to calculate MNDWI (Modified Normalized Difference Water Index)
    function calculateMNDWI(image) {
      // MNDWI = (Green - SWIR1) / (Green + SWIR1)
      // Sentinel-2 bands: Green = B3, SWIR1 = B11
      return image.normalizedDifference(['B3', 'B11']).rename('MNDWI');
    }

    // Function to get a median composite and MNDWI for a given date range
    async function getWaterExtent(startDate, endDate, geom, tag) {
      let collection = ee.ImageCollection('COPERNICUS/S2_SR')
                           .filterBounds(geom)
                           .filterDate(startDate, endDate)
                           .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 20)); // Pre-filter for less cloudy images

      const initialSize = await collection.size().getInfo();

      if (initialSize === 0) {
        console.log(`No images found for ${tag} in period ${startDate} to ${endDate}.`);
        return { area: null, count: 0, cloud_percentage: null };
      }

      collection = collection.map(maskS2clouds);
      const medianImage = collection.median();

      if (medianImage.bandNames().size().getInfo() === 0) {
        console.log(`No valid bands after cloud masking for ${tag}.`);
        return { area: null, count: 0, cloud_percentage: null };
      }

      const mndwi = calculateMNDWI(medianImage);
      // Threshold MNDWI to create a water mask (MNDWI > 0)
      const waterMask = mndwi.gt(0).rename('water_mask');

      // Calculate the area of water pixels
      const waterAreaImage = waterMask.multiply(ee.Image.pixelArea()).divide(1000000); // Area in square kilometers

      const stats = await waterAreaImage.reduceRegion({
        reducer: ee.Reducer.sum().unweighted(), // Use unweighted to sum pixel areas
        geometry: geom,
        scale: 10, // Sentinel-2 resolution
        maxPixels: 1e9,
        tileScale: 16 // Increase tileScale to avoid memory errors for large areas
      }).getInfo();

      const area_sqkm = stats['water_mask'];

      // Also get pixel count for validation
      const pixelCount = waterMask.reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: geom,
        scale: 10,
        maxPixels: 1e9,
        tileScale: 16
      }).get('water_mask').getInfo();

      const cloud_perc = await collection.aggregate_mean('CLOUDY_PIXEL_PERCENTAGE').getInfo();

      console.log(`${tag} Images: ${initialSize} (Cloud %: ${cloud_perc ? cloud_perc.toFixed(2) : 'N/A'})`);

      return { area: area_sqkm, count: pixelCount, cloud_percentage: cloud_perc };
    }

    // Get water extent for Period 1
    const result1 = await getWaterExtent(date1_start, date1_end, geometry, '2019-02-02');
    if (result1.area === null || result1.count === 0) {
      if (result1.area === null) {
         console.log('C1'); // No images found for 2019 or no valid bands
         return;
      } else {
         console.log('C2'); // No valid pixels after masking
         return;
      }
    }

    // Get water extent for Period 2
    const result2 = await getWaterExtent(date2_start, date2_end, geometry, '2021-05-14');
    if (result2.area === null || result2.count === 0) {
      if (result2.area === null) {
        console.log('C1'); // No images found for 2021 or no valid bands
        return;
      } else {
        console.log('C2'); // No valid pixels after masking
        return;
      }
    }

    // 4. Calculation & 5. Validation & Final Answer
    const area1 = result1.area;
    const area2 = result2.area;

    if (area1 === undefined || area1 === null || isNaN(area1) ||
        area2 === undefined || area2 === null || isNaN(area2)) {
      console.log('C3'); // Calculation failure
      return;
    }

    console.log(`2019-02-02 Water Area: ${area1.toFixed(2)} sq km (Pixels: ${result1.count})`);
    console.log(`2021-05-14 Water Area: ${area2.toFixed(2)} sq km (Pixels: ${result2.count})`);

    const shrank = area2 < area1;

    if (shrank) {
      console.log('A'); // Yes
    } else {
      console.log('B'); // No
    }

  } catch (error) {
    console.error("An error occurred:", error);
    console.log('D'); // General error or memory issue
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
